  GRAMMAR.push({ structure: "明明", usage: "\"Rõ ràng là\": sau 明明 là một sự thật hiển nhiên; trước hoặc sau thường có một vế mâu thuẫn với sự thật đó.", lesson: "P4-14", examples: [ex("才不是謙虛！明明心裡高興得要命，還要假裝不在乎。", '', "Đâu phải khiêm tốn! Rõ ràng trong lòng vui muốn chết, còn giả vờ không quan tâm."), ex("那邊明明還有一個停車位，他卻告訴我們都滿了，真可惡！", '', "Bên kia rõ ràng còn một chỗ đỗ xe, anh ta lại bảo chúng tôi hết chỗ rồi, thật đáng ghét!")] });
  GRAMMAR.push({ structure: "連A帶B", usage: "\"Cả A lẫn B\": gộp hai đối tượng (hoặc hai hành động diễn ra cùng lúc) lại với nhau.", lesson: "P4-14", examples: [ex("我們連大人帶小孩才七八個人，你媽媽卻準備了一隻雞、兩條魚、三盤肉……", '', "Cả người lớn lẫn trẻ con chúng tôi chỉ bảy tám người, mẹ bạn lại chuẩn bị một con gà, hai con cá, ba đĩa thịt…"), ex("小錢騎摩托車騎得太快，結果轉彎的時候，連人帶車摔倒在人行道上。", '', "Tiểu Tiền đi xe máy quá nhanh, lúc rẽ cả người lẫn xe ngã ra vỉa hè.")] });
  GRAMMAR.push({ structure: "一口氣", usage: "\"Một hơi, một mạch\": làm liền một lèo không nghỉ.", lesson: "P4-14", examples: [ex("哇！厲害，厲害！一口氣說這麼多。", '', "Oa! Giỏi thật! Nói một hơi được nhiều thế."), ex("他一口氣跑了四百公尺才停下來。", '', "Anh ấy chạy một mạch bốn trăm mét mới dừng lại.")] });
  GRAMMAR.push({ structure: "把A當做B", usage: "\"Coi A là B, lấy A làm B\" (thường là nhầm lẫn hoặc dùng sai mục đích).", lesson: "P4-14", examples: [ex("聽說你們有人把白蘭地當做果汁，不停地乾杯。", '', "Nghe nói bên các bạn có người coi brandy như nước ép, cạn ly liên tục."), ex("我去替張教授打掃房間，結果他的學生把我當做小偷了。", '', "Tôi đi dọn phòng giúp giáo sư Trương, kết quả sinh viên của ông ấy tưởng tôi là kẻ trộm.")] });
  GRAMMAR.push({ structure: "不見得", usage: "\"Chưa chắc\": phủ định nhẹ nhàng một nhận định, cho rằng điều đó không nhất định đúng.", lesson: "P4-14", examples: [ex("我們不會喝酒，你們也不見得會喝茶啊！", '', "Chúng tôi không biết uống rượu, các bạn cũng chưa chắc biết uống trà đâu!"), ex("你同事的錄音機跟你丟的一樣，不見得就是他偷了你的。", '', "Máy ghi âm của đồng nghiệp giống cái bạn bị mất, chưa chắc là anh ta lấy của bạn.")] });
  GRAMMAR.push({ structure: "簡直", usage: "\"Quả thực, đúng là\": nói quá để nhấn mạnh mức độ, gần như đúng hoàn toàn.", lesson: "P4-14", examples: [ex("茶裡加了糖、牛奶，還能叫茶嗎？簡直可笑。", '', "Trà mà cho đường, cho sữa thì còn gọi là trà được sao? Thật nực cười."), ex("我弟弟在公共場所大聲吵鬧，一點也不管別人，我簡直丟臉死了。", '', "Em trai tôi làm ồn ở nơi công cộng, chẳng để ý ai, tôi quả thực xấu hổ chết đi được.")] });
  GRAMMAR.push({ structure: "終於", usage: "\"Cuối cùng (cũng)\": sau một thời gian dài hoặc nhiều khó khăn mới đạt được kết quả.", lesson: "P4-14", examples: [ex("哈！我終於有機會取笑你了。", '', "Ha! Cuối cùng tôi cũng có dịp trêu bạn."), ex("警察查了好幾個月，終於查出來是誰偷了我的錄音機了。", '', "Cảnh sát điều tra mấy tháng, cuối cùng cũng tìm ra ai trộm máy ghi âm của tôi.")] });
  GRAMMAR.push({ structure: "看在……的份上", usage: "\"Nể mặt…, vì (tình nghĩa)…\": vì một mối quan hệ hay lý do nào đó mà chấp nhận, tha thứ hoặc giúp đỡ.", lesson: "P4-14", examples: [ex("大人不記小人過，看在我們是同學的份上，原諒你一次！", '', "Người lớn không chấp kẻ nhỏ, nể tình chúng ta là bạn học, tha cho bạn một lần!"), ex("你室友雖然偷了你的錄音機，可是看在他是第一次偷東西的份上，原諒他吧！", '', "Bạn cùng phòng tuy lấy máy ghi âm của bạn, nhưng nể tình là lần đầu, tha cho cậu ấy đi!")] });
  CONVERSATIONS.push({"title":"實用視聽華語4 · 第十四課 來一段相聲","lines":[{"speaker":"","zh":"（教室講台上）","pinyin":"","en":"(Trên bục giảng lớp học)"},{"speaker":"偉立","zh":"（穿西裝打領帶）高偉立。","pinyin":"","en":"(Mặc com-lê thắt cà vạt) Cao Vỹ Lập."},{"speaker":"欣欣","zh":"（穿旗袍）歐陽欣欣。","pinyin":"","en":"(Mặc sườn xám) Âu Dương Hân Hân."},{"speaker":"偉立","zh":"（和欣欣邊說邊彎腰）上台一鞠躬。各位女士、各位先生，大家好。","pinyin":"","en":"(Cùng Hân Hân vừa nói vừa cúi người) Lên sân khấu xin cúi chào. Thưa quý bà, quý ông, xin chào mọi người."},{"speaker":"欣欣","zh":"學期快要結束了，我們來給各位說一段相聲，讓大家輕鬆輕鬆。","pinyin":"","en":"Học kỳ sắp kết thúc, chúng tôi xin tấu một đoạn tấu nói để mọi người thư giãn."},{"speaker":"偉立","zh":"哎呀！親愛的，好久不見了！（轉身擁抱欣欣）","pinyin":"","en":"Ôi chao! Em yêu, lâu quá không gặp! (Quay người ôm Hân Hân)"},{"speaker":"欣欣","zh":"（用手推開）欸，欸，欸，你幹什麼？不要動手動腳，你想吃我豆腐啊？！","pinyin":"","en":"(Lấy tay đẩy ra) Ê, ê, ê, anh làm gì vậy? Đừng có động tay động chân, anh định sàm sỡ tôi à?!"},{"speaker":"偉立","zh":"對不起，我忘了你們不在公共場所摟摟抱抱。幸虧我剛才沒親你，要不然你要打我耳光了。","pinyin":"","en":"Xin lỗi, tôi quên là các bạn không ôm ấp nơi công cộng. May mà nãy tôi không hôn bạn, không thì bạn tát tôi rồi."},{"speaker":"欣欣","zh":"一點也不錯！還有，你也別叫我「親愛的」，好肉麻啊！","pinyin":"","en":"Chẳng sai chút nào! Còn nữa, anh cũng đừng gọi tôi là \"em yêu\", sến quá đi!"},{"speaker":"偉立","zh":"好吧！下次不敢了。欸，你今天的髮型配上旗袍看起來特別漂亮。","pinyin":"","en":"Được rồi! Lần sau không dám nữa. Này, kiểu tóc hôm nay của bạn phối với sườn xám trông đặc biệt đẹp."},{"speaker":"欣欣","zh":"哪裡！哪裡！我對自己的身材不太滿意，所以平常都不敢穿。倒是你今天穿得這麼整齊，這麼帥，我差點都不認得了。","pinyin":"","en":"Đâu có! Đâu có! Tôi không hài lòng lắm với vóc dáng của mình nên bình thường không dám mặc. Ngược lại hôm nay anh ăn mặc chỉnh tề, đẹp trai thế, tôi suýt không nhận ra."},{"speaker":"偉立","zh":"謝謝，其實我本來就很帥，只是平常對穿衣服不講究，看起來不修邊幅而已。","pinyin":"","en":"Cảm ơn, thật ra tôi vốn đẹp trai, chỉ là bình thường không chú trọng ăn mặc nên trông xuề xòa thôi."},{"speaker":"欣欣","zh":"你的臉皮真厚，我不過隨便說說，你就這麼得意。我們謙虛多了。","pinyin":"","en":"Anh thật mặt dày, tôi chỉ nói đại thôi mà anh đắc ý thế. Chúng tôi khiêm tốn hơn nhiều."},{"speaker":"偉立","zh":"才不是謙虛！明明心裡高興得要命，還要假裝不在乎。我實在弄不懂你們的「謙虛」。","pinyin":"","en":"Đâu phải khiêm tốn! Rõ ràng trong lòng vui muốn chết, còn giả vờ không quan tâm. Tôi thật không hiểu nổi cái \"khiêm tốn\" của các bạn."},{"speaker":"欣欣","zh":"這話怎麼說？","pinyin":"","en":"Sao lại nói thế?"},{"speaker":"偉立","zh":"像上次伯母請我吃飯，她說沒什麼菜，我就先吃了一個三明治才去，結果害我吃得差點兒站不起來。","pinyin":"","en":"Như lần trước bác gái mời tôi ăn cơm, bác bảo chẳng có món gì, tôi bèn ăn trước một cái sandwich rồi mới đi, kết quả ăn đến suýt không đứng dậy nổi."},{"speaker":"欣欣","zh":"誰叫你不懂我們的規矩，活該！","pinyin":"","en":"Ai bảo anh không hiểu phép tắc của chúng tôi, đáng đời!"},{"speaker":"偉立","zh":"我們連大人帶小孩才七八個人，你媽媽卻準備了一隻雞、兩條魚、三盤肉、四樣青菜、五種飲料，再加上冰淇淋、蘋果派、巧克力蛋糕，你說怎麼吃得完？","pinyin":"","en":"Cả người lớn lẫn trẻ con chúng tôi mới bảy tám người, mẹ bạn lại chuẩn bị một con gà, hai con cá, ba đĩa thịt, bốn món rau, năm loại đồ uống, thêm cả kem, bánh táo, bánh sô-cô-la, bạn bảo ăn sao cho hết?"},{"speaker":"欣欣","zh":"（拍手）哇！厲害，厲害！一口氣說這麼多。你不知道，華人最好客，就怕客人吃不飽。哪兒像你上次請我們幾個人吃飯，就是一碗沙拉、一隻小雞，害我都不敢放心地吃。還沒回到家，肚子就餓了。","pinyin":"","en":"(Vỗ tay) Oa! Giỏi, giỏi thật! Nói một hơi được nhiều thế. Anh không biết đấy, người Hoa hiếu khách nhất, chỉ sợ khách ăn không no. Đâu như lần trước anh mời mấy người chúng tôi ăn, chỉ có một bát xa lát, một con gà nhỏ, làm tôi chẳng dám ăn thoải mái. Chưa về đến nhà bụng đã đói."},{"speaker":"偉立","zh":"我怎麼知道你那麼能吃？！","pinyin":"","en":"Sao tôi biết bạn ăn khỏe thế?!"},{"speaker":"欣欣","zh":"誰有你那麼能吃啊？我只是替你擔心，萬一東西不夠吃，多丟人啊！","pinyin":"","en":"Ai ăn khỏe bằng anh? Tôi chỉ lo cho anh thôi, lỡ đồ ăn không đủ thì mất mặt biết bao!"},{"speaker":"偉立","zh":"我倒覺得吃不完才浪費。聽說你們有人把白蘭地當做果汁，不停地乾杯。根本不會喝酒嘛！","pinyin":"","en":"Tôi lại thấy ăn không hết mới là lãng phí. Nghe nói bên các bạn có người coi brandy như nước ép, cạn ly liên tục. Hoàn toàn không biết uống rượu!"},{"speaker":"欣欣","zh":"我們不會喝酒，你們也不見得會喝茶啊！茶裡加了糖、牛奶，還能叫茶嗎？簡直可笑。","pinyin":"","en":"Chúng tôi không biết uống rượu, các anh cũng chưa chắc biết uống trà đâu! Trà mà cho đường, cho sữa thì còn gọi là trà được sao? Thật nực cười."},{"speaker":"偉立","zh":"哎喲，生氣了？說著玩的，何必那麼認真！","pinyin":"","en":"Ôi chao, giận rồi à? Nói đùa thôi mà, việc gì phải nghiêm túc thế!"},{"speaker":"欣欣","zh":"我也是說著玩的啊！還有一件事，你注意到沒有？我們是怎麼看書的？從上往下念。（邊說邊表演）你們呢？","pinyin":"","en":"Tôi cũng nói đùa thôi! Còn một chuyện nữa, anh có để ý không? Chúng tôi đọc sách thế nào? Đọc từ trên xuống dưới. (Vừa nói vừa diễn) Còn các anh?"},{"speaker":"偉立","zh":"我們是從左往右念。（也邊說邊表演）","pinyin":"","en":"Chúng tôi đọc từ trái sang phải. (Cũng vừa nói vừa diễn)"},{"speaker":"欣欣","zh":"欸，高偉立，你幹嘛直搖頭啊？是不好看，還是不同意啊？","pinyin":"","en":"Ê, Cao Vỹ Lập, sao anh cứ lắc đầu mãi thế? Là không hay, hay là không đồng ý?"},{"speaker":"偉立","zh":"啊！我上當了。（故意打了一個噴嚏，欣欣沒反應）哈！我終於有機會取笑你了。剛才我打噴嚏，你應該說什麼啊？","pinyin":"","en":"A! Tôi mắc lừa rồi. (Cố ý hắt xì một cái, Hân Hân không phản ứng) Ha! Cuối cùng tôi cũng có dịp trêu bạn. Vừa rồi tôi hắt xì, bạn phải nói gì nào?"},{"speaker":"欣欣","zh":"噢！對不起！對不起！我們沒這個習慣，那句話我一時還說不來。","pinyin":"","en":"Ồ! Xin lỗi! Xin lỗi! Chúng tôi không có thói quen này, câu đó tôi nhất thời chưa nói quen."},{"speaker":"偉立","zh":"大人不記小人過，看在我們是同學的份上，原諒你一次！","pinyin":"","en":"Người lớn không chấp kẻ nhỏ, nể tình chúng ta là bạn học, tha cho bạn một lần!"},{"speaker":"欣欣","zh":"好啦！我也懶得再罵你了。下台吧！觀眾已經不耐煩了。你看，有人在打哈欠了。","pinyin":"","en":"Thôi được! Tôi cũng chẳng buồn mắng anh nữa. Xuống thôi! Khán giả mất kiên nhẫn rồi. Anh xem, có người đang ngáp kìa."},{"speaker":"欣欣","zh":"（和偉立一起）歐陽欣欣、高偉立，下台一鞠躬。","pinyin":"","en":"(Cùng Vỹ Lập) Âu Dương Hân Hân, Cao Vỹ Lập, xuống sân khấu xin cúi chào."}],"questions":[{"prompt":"偉立和欣欣為什麼表演相聲？","options":["學期快要結束了，讓大家輕鬆輕鬆","他們要參加比賽","老師叫他們表演","他們想賺錢"],"correct":0},{"prompt":"偉立擁抱欣欣的時候，欣欣有什麼反應？","options":["用手推開，說他動手動腳","很高興地也擁抱他","打了他一個耳光","轉身就走"],"correct":0},{"prompt":"偉立為什麼說弄不懂華人的「謙虛」？","options":["明明心裡高興得要命，還要假裝不在乎","因為華人都很驕傲","因為華人不會說客氣話","因為欣欣不謙虛"],"correct":0},{"prompt":"上次伯母說「沒什麼菜」，結果怎麼樣？","options":["準備了很多菜，偉立先吃了三明治，吃得差點站不起來","真的沒什麼菜，偉立沒吃飽","伯母沒請偉立吃飯","偉立吃完就生病了"],"correct":0},{"prompt":"欣欣覺得偉立上次請客怎麼樣？","options":["只有一碗沙拉、一隻小雞，不敢放心吃，回家前就餓了","菜太多，吃不完","太浪費了","菜很好吃"],"correct":0},{"prompt":"欣欣認為西方人喝茶有什麼可笑？","options":["茶裡加了糖、牛奶","喝得太多","只喝冰茶","不用茶杯"],"correct":0},{"prompt":"偉立打噴嚏時，欣欣為什麼沒說什麼？","options":["她們沒有這個習慣，一時說不來","她生氣了","她沒聽見","她覺得不禮貌"],"correct":0}]});
