  GRAMMAR.push({ structure: "跟……相當", usage: "\"Tương đương với…\": hai đối tượng ngang nhau về mức độ, giá trị, vai trò.", lesson: "P5-02", examples: [ex("春節的重要性跟西方的聖誕節相當，可是風俗習慣完全不同。", '', "Tầm quan trọng của Tết tương đương với lễ Giáng sinh phương Tây, nhưng phong tục hoàn toàn khác."), ex("有些人每年花在旅遊上的錢跟薪水相當。", '', "Có người mỗi năm chi cho du lịch ngang với tiền lương.")] });
  GRAMMAR.push({ structure: "至於", usage: "\"Còn về…\": chuyển sang nói một mặt / đối tượng liên quan khác.", lesson: "P5-02", examples: [ex("至於「正月」，就是陰曆的第一個月。", '', "Còn \"tháng Giêng\" là tháng đầu tiên của âm lịch."), ex("我只知道這個宗教常舉行祭祀儀式，至於祭拜什麼神，我就不清楚了。", '', "Tôi chỉ biết tôn giáo này hay tổ chức nghi lễ cúng tế, còn thờ vị thần nào thì tôi không rõ.")] });
  GRAMMAR.push({ structure: "凡是……都……", usage: "\"Phàm là…, hễ là… đều…\": mọi đối tượng thuộc phạm vi đó đều như nhau, không có ngoại lệ.", lesson: "P5-02", examples: [ex("天一亮就是正月初一，凡是跟別人見面的人，都互相說「恭喜」。", '', "Trời vừa sáng là mùng Một, hễ ai gặp nhau đều chúc nhau \"Cung hỷ\"."), ex("凡是有環保觀念的人都會做垃圾分類。", '', "Phàm là người có ý thức bảo vệ môi trường đều phân loại rác.")] });
  GRAMMAR.push({ structure: "把……定為……", usage: "\"Lấy… làm…, quy định… là…\": chọn một ngày / thời điểm làm dịp gì đó.", lesson: "P5-02", examples: [ex("1978年起，政府把這個能發揚中華文化的日子定為觀光節。", '', "Từ năm 1978, chính phủ lấy ngày có thể phát huy văn hóa Trung Hoa này làm Ngày du lịch."), ex("政府把孔子的生日定為教師節。", '', "Chính phủ lấy ngày sinh của Khổng Tử làm Ngày Nhà giáo.")] });
  CONVERSATIONS.push({"title":"實用視聽華語5 · 第二課 春節","lines":[{"speaker":"","zh":"在華人世界，最重要的節日就是「過年」，也就是「春節」。春節的重要性跟西方的聖誕節相當，可是風俗習慣完全不同。春節的正式活動雖然是從臘月二十三到正月十七，其實臘月一開始，大街小巷就充滿了過年的氣氛。這種歡樂的氣氛會持續一個半月之久。","pinyin":"","en":"Trong thế giới người Hoa, ngày lễ quan trọng nhất là \"ăn Tết\", tức là \"Tết xuân\". Tầm quan trọng của Tết tương đương lễ Giáng sinh phương Tây, nhưng phong tục hoàn toàn khác. Các hoạt động chính thức của Tết tuy kéo dài từ 23 tháng Chạp đến 17 tháng Giêng, nhưng thật ra tháng Chạp vừa bắt đầu là phố lớn ngõ nhỏ đã ngập tràn không khí Tết. Không khí vui vẻ này kéo dài tới một tháng rưỡi."},{"speaker":"","zh":"有些人也許會覺得奇怪，什麼是「臘月」呢？「臘」是古代祭祀的儀式，因為用肉類來祭祖，所以叫「臘」祭；又由於臘祭在陰曆十二月舉行，所以那個月就叫「臘月」。至於「正月」，就是陰曆的第一個月；正月的第一天，春天開始，所以又叫「春節」。","pinyin":"","en":"Có người có thể thấy lạ, \"tháng Chạp\" (lạp nguyệt) là gì? \"Lạp\" là nghi lễ cúng tế thời cổ, vì dùng thịt để cúng tổ tiên nên gọi là lễ \"lạp\"; lại vì lễ này tổ chức vào tháng 12 âm lịch nên tháng đó gọi là \"lạp nguyệt\". Còn \"tháng Giêng\" là tháng đầu tiên của âm lịch; ngày đầu tháng Giêng là khởi đầu mùa xuân nên còn gọi là \"Tết xuân\"."},{"speaker":"","zh":"臘月二十三這天，傳說是灶神升天的日子，也叫做「過小年」。大家除了把廚房打掃乾淨以外，還得請灶神吃糖，這樣祂向天帝報告的時候，就都會說好話，而讓一家人一年都順利平安。過了這天以後，家家就忙著打掃、整理內外、辦年貨等，積極準備過年。","pinyin":"","en":"Ngày 23 tháng Chạp, tương truyền là ngày ông Táo lên trời, còn gọi là \"Tết nhỏ\". Ngoài dọn sạch bếp, mọi người còn phải mời ông Táo ăn kẹo, để khi báo cáo với Ngọc Hoàng ông chỉ nói lời tốt, giúp cả nhà một năm thuận lợi bình an. Qua ngày này, nhà nhà bận rộn dọn dẹp, sắp xếp trong ngoài, sắm đồ Tết, hăng hái chuẩn bị đón Tết."},{"speaker":"","zh":"關於過年，也有一個傳說。「年」這個字，古代是指一個兇惡的怪獸，平常住在深山裡，每年到了除夕晚上就下山，到處傷人。有人發現牠怕紅色，遇見有紅色大門的人家，就過門不入。於是大家在門上貼紅紙，叫「春聯」；躲在屋裡一夜不敢睡覺，叫「守歲」。深夜十二點以後，家家戶戶接二連三放鞭炮來嚇走「年」。天一亮就是正月初一，凡是跟別人見面的人，都互相說「恭喜」，意思是還好大家都沒被「年」傷到。","pinyin":"","en":"Về Tết cũng có một truyền thuyết. Chữ \"niên\" thời cổ chỉ một con quái thú hung ác, bình thường sống trong núi sâu, mỗi năm đến tối giao thừa lại xuống núi làm hại người khắp nơi. Có người phát hiện nó sợ màu đỏ, gặp nhà có cửa đỏ là đi qua không vào. Thế là mọi người dán giấy đỏ lên cửa, gọi là \"câu đối Tết\"; trốn trong nhà cả đêm không dám ngủ, gọi là \"thủ tuế\". Sau 12 giờ đêm, nhà nhà liên tiếp đốt pháo để dọa \"Niên\" chạy đi. Trời vừa sáng là mùng Một, hễ ai gặp nhau đều chúc \"Cung hỷ\", ý là may mà mọi người không bị \"Niên\" làm hại."},{"speaker":"","zh":"「除夕」有除去舊年迎接新年的意思。這天大家忙著貼春聯、祭祖、放鞭炮，到了晚上，一家人團圓，一起吃年夜飯。飯後，孩子向長輩拜年，領壓歲錢。接近午夜的時候，就吃長得像元寶的餃子，討個吉利，然後守歲。正月初一就是新年，大家穿上新衣，互相拜年。在春節期間，一定要多說吉利話，不可罵人；萬一打破了東西，就馬上說「歲歲（碎碎）平安」。","pinyin":"","en":"\"Trừ tịch\" có nghĩa là bỏ năm cũ đón năm mới. Ngày này mọi người bận dán câu đối, cúng tổ tiên, đốt pháo; tối đến cả nhà sum họp ăn cơm tất niên. Ăn xong, trẻ con chúc Tết người lớn, nhận tiền mừng tuổi. Gần nửa đêm ăn sủi cảo hình nén vàng để lấy may, rồi thức đón giao thừa. Mùng Một là năm mới, mọi người mặc quần áo mới, chúc Tết nhau. Trong dịp Tết nhất định phải nói nhiều lời may mắn, không được mắng người; lỡ làm vỡ đồ thì nói ngay \"tuế tuế bình an\"."},{"speaker":"","zh":"春節最後一個歡樂的高潮是正月十五的「元宵節」。這天到處張燈結綵，玩花燈、猜燈謎、吃元宵（湯圓），十分熱鬧。1978年起，政府把這個能發揚中華文化的日子定為觀光節。到了1992年，又開始舉辦「臺北燈會」，每年都舉行點燈儀式、猜燈謎晚會，配合各式花燈，以及民間傳統小吃、民俗表演，吸引國內外的觀光客。一直到元宵節過後幾天，春節的活動才完全結束。","pinyin":"","en":"Cao trào vui vẻ cuối cùng của Tết là \"Tết Nguyên Tiêu\" rằm tháng Giêng. Ngày này khắp nơi giăng đèn kết hoa, chơi đèn lồng, đoán câu đố đèn, ăn bánh trôi, vô cùng náo nhiệt. Từ năm 1978, chính phủ lấy ngày có thể phát huy văn hóa Trung Hoa này làm Ngày du lịch. Đến năm 1992 lại bắt đầu tổ chức \"Hội đèn lồng Đài Bắc\", năm nào cũng có lễ thắp đèn, đêm hội đố đèn, cùng đủ loại đèn lồng, món ăn dân gian truyền thống, biểu diễn dân gian, thu hút du khách trong và ngoài nước. Mãi đến vài ngày sau Nguyên Tiêu, các hoạt động Tết mới hoàn toàn kết thúc."},{"speaker":"","zh":"由於受到西方的影響，最近大家也開始熱烈慶祝陽曆一月一日的「元旦」了。但無論如何，春節在華人心中還是最重要的節日。","pinyin":"","en":"Do chịu ảnh hưởng phương Tây, gần đây mọi người cũng bắt đầu nhiệt liệt đón \"Tết Dương lịch\" ngày 1/1. Nhưng dù thế nào, Tết xuân vẫn là ngày lễ quan trọng nhất trong lòng người Hoa."}],"questions":[{"prompt":"臘月二十三為什麼叫「過小年」？","options":["傳說是灶神升天的日子","是一年的最後一天","是春節的第一天","是元宵節"],"correct":0},{"prompt":"為什麼要請灶神吃糖？","options":["讓祂向天帝報告的時候說好話","因為灶神喜歡吃甜的","為了讓孩子高興","因為糖代表發財"],"correct":0},{"prompt":"「年」這個怪獸怕什麼？","options":["紅色","鞭炮的聲音","白色","月亮"],"correct":0},{"prompt":"為什麼叫「臘月」？","options":["臘祭在陰曆十二月舉行","那個月很冷","那個月要吃臘肉","那個月要打掃"],"correct":0},{"prompt":"打破了東西要說什麼？","options":["歲歲（碎碎）平安","恭喜發財","新年快樂","對不起"],"correct":0},{"prompt":"政府把元宵節定為什麼節日？","options":["觀光節","教師節","春節","元旦"],"correct":0}]});
