  GRAMMAR.push({ structure: "無不", usage: "\"Không ai không, đều\": phủ định kép để khẳng định mạnh — tất cả đều như vậy.", lesson: "P5-05", examples: [ex("各國選手無不摩拳擦掌，希望在大會中奪得金牌與光榮。", '', "Tuyển thủ các nước ai cũng háo hức, mong giành huy chương vàng và vinh quang."), ex("看了這部感人的電影，觀眾無不流下淚來。", '', "Xem bộ phim cảm động này, khán giả không ai không rơi nước mắt.")] });
