  GRAMMAR.push({ structure: "所謂……是指……", usage: "\"Cái gọi là… là chỉ…\": giải thích định nghĩa một khái niệm.", lesson: "P5-08", examples: [ex("所謂「單親家庭」，是指夫妻因離婚、分居、死亡、遺棄、服刑等原因，而造成雙親之一單獨與子女生活的家庭。", '', "Cái gọi là \"gia đình đơn thân\" là chỉ gia đình mà do ly hôn, ly thân, qua đời, ruồng bỏ, ngồi tù… khiến chỉ còn một trong hai cha mẹ sống với con."), ex("所謂單身貴族是指沒結婚、收入不錯的人。", '', "Cái gọi là \"quý tộc độc thân\" là chỉ người chưa kết hôn, thu nhập khá.")] });
  GRAMMAR.push({ structure: "只要……仍能……", usage: "\"Chỉ cần… thì vẫn có thể…\": dù hoàn cảnh khó, đáp ứng điều kiện thì vẫn đạt được.", lesson: "P5-08", examples: [ex("只要單親父母面對問題，重新安排生活，家人仍能過得自在而有意義。", '', "Chỉ cần cha mẹ đơn thân đối mặt vấn đề, sắp xếp lại cuộc sống, gia đình vẫn sống thoải mái và có ý nghĩa."), ex("只要每天運動，雖然年紀大了，仍能保持身體的健康。", '', "Chỉ cần vận động mỗi ngày, dù tuổi đã cao vẫn giữ được sức khỏe.")] });
  GRAMMAR.push({ structure: "則", usage: "\"Thì, còn\": nối vế đối chiếu với vế trước (văn viết).", lesson: "P5-08", examples: [ex("如果原來就是職業婦女，雖有工作能力，但因家中少了一份收入，經濟上可能面臨一些難題；若是家庭主婦，則可能因此不得不出外工作而增加生活的壓力。", '', "Nếu vốn là phụ nữ đi làm, tuy có khả năng làm việc nhưng nhà thiếu một nguồn thu, kinh tế có thể gặp khó; còn nếu là nội trợ thì có thể buộc phải ra ngoài làm việc, tăng áp lực cuộc sống."), ex("以前的人用異樣的眼光看離婚的人，現在則不同了。", '', "Trước đây người ta nhìn người ly hôn bằng ánh mắt khác thường, bây giờ thì khác rồi.")] });
  GRAMMAR.push({ structure: "要是……最好先……", usage: "\"Nếu…, tốt nhất nên… trước\": đưa ra lời khuyên cho một tình huống.", lesson: "P5-08", examples: [ex("要是情緒不穩定，體力難以負擔，最好先把孩子托給親人照顧一陣子。", '', "Nếu tâm lý không ổn định, sức lực khó gánh, tốt nhất nên gửi con cho người thân chăm một thời gian."), ex("學生要是想學書法，最好先買一枝好毛筆。", '', "Học sinh nếu muốn học thư pháp, tốt nhất mua trước một cây bút lông tốt.")] });
  CONVERSATIONS.push({"title":"實用視聽華語5 · 第八課 單親家庭","lines":[{"speaker":"","zh":"所謂「單親家庭」，是指夫妻因離婚、分居、死亡、遺棄、服刑等原因，而造成雙親之一單獨與子女生活的家庭。此外，未婚生子，或是出於個人選擇的不婚生子，也會製造單親家庭。","pinyin":"","en":"Cái gọi là \"gia đình đơn thân\" là chỉ gia đình mà vì ly hôn, ly thân, qua đời, ruồng bỏ, ngồi tù… khiến chỉ còn một trong hai cha mẹ sống với con. Ngoài ra, sinh con khi chưa cưới, hoặc chọn không kết hôn mà sinh con cũng tạo ra gia đình đơn thân."},{"speaker":"","zh":"現代人大部分都改變了以往的刻板印象，能夠了解單親家庭不是破碎家庭，更不一定會過不幸的生活，只要單親父母面對問題，重新安排生活，家人仍能過得自在而有意義。","pinyin":"","en":"Phần lớn người hiện đại đã thay đổi ấn tượng rập khuôn trước đây, hiểu rằng gia đình đơn thân không phải gia đình tan vỡ, càng không nhất định sống bất hạnh; chỉ cần cha mẹ đơn thân đối mặt vấn đề, sắp xếp lại cuộc sống, gia đình vẫn sống thoải mái và có ý nghĩa."},{"speaker":"","zh":"過去離婚的婦女，除了夫妻分離的痛苦，也可能因此要忍痛離開子女，有時還得面對社會異樣的眼光。現在離婚的人多了，社會不再歧視她們，有些人還自動放棄孩子，享受自由。不過大部分離婚的婦女，仍然要獨力撫養孩子。如果原來就是職業婦女，雖有工作能力，但因家中少了一份收入，經濟上可能面臨一些難題；若是家庭主婦，則可能因此不得不出外工作而增加生活的壓力。至於喪偶的妻子，要承受莫大的傷痛，必須付出更大的心力來克服一切。","pinyin":"","en":"Phụ nữ ly hôn trước đây, ngoài nỗi đau vợ chồng chia lìa, còn có thể phải đành lòng xa con, đôi khi còn đối mặt ánh mắt khác thường của xã hội. Nay người ly hôn nhiều hơn, xã hội không còn kỳ thị, có người còn tự nguyện từ bỏ con để hưởng tự do. Nhưng đa số phụ nữ ly hôn vẫn phải một mình nuôi con. Nếu vốn là phụ nữ đi làm, tuy có khả năng làm việc nhưng nhà thiếu một nguồn thu, kinh tế có thể gặp khó; nếu là nội trợ thì có thể buộc phải ra ngoài làm việc, tăng áp lực cuộc sống. Còn người vợ góa chồng phải chịu nỗi đau to lớn, phải bỏ ra nhiều tâm sức hơn để vượt qua tất cả."},{"speaker":"","zh":"單親爸爸有兩種情況，一種人忙著約會，希望女友可以分擔照顧孩子的責任，有的人甚至把這種責任完全丟給女友。另一種人往往害怕讓孩子受到傷害，因此除非時機成熟，他不願女友出現在孩子面前。有些離婚的單親爸爸，還要付贍養費，這種經濟壓力顯然會促使他們逃避婚姻。","pinyin":"","en":"Bố đơn thân có hai kiểu: kiểu thứ nhất mải hẹn hò, mong bạn gái chia sẻ trách nhiệm chăm con, có người thậm chí đẩy hết trách nhiệm cho bạn gái. Kiểu kia thường sợ con bị tổn thương, nên trừ khi thời cơ chín muồi, anh không muốn bạn gái xuất hiện trước mặt con. Một số bố đơn thân ly hôn còn phải trả tiền cấp dưỡng, áp lực kinh tế này rõ ràng khiến họ né tránh hôn nhân."},{"speaker":"","zh":"遭遇困難的人與其痛苦生活，不如選擇接受事實，面對問題。單親父母首先應該學習處理自己的情緒，給自己成長的機會。要是情緒不穩定，體力難以負擔，最好先把孩子托給親人照顧一陣子，坦然接受朋友、同事精神上的支持與幫助，或是找專業的輔導機構，尋求適應生活的方法。另外，根據自己的體能、時間、個性和條件，參與適當的社會團體或學習技藝，都能讓自己成長。","pinyin":"","en":"Người gặp khó khăn thay vì sống đau khổ, chi bằng chọn chấp nhận sự thật, đối mặt vấn đề. Cha mẹ đơn thân trước tiên nên học cách xử lý cảm xúc, cho mình cơ hội trưởng thành. Nếu tâm lý không ổn định, sức lực khó gánh, tốt nhất gửi con cho người thân chăm một thời gian, bình thản đón nhận sự ủng hộ tinh thần của bạn bè, đồng nghiệp, hoặc tìm cơ quan tư vấn chuyên nghiệp để tìm cách thích nghi. Ngoài ra, tùy theo thể lực, thời gian, tính cách và điều kiện, tham gia đoàn thể xã hội phù hợp hoặc học kỹ năng đều giúp mình trưởng thành."},{"speaker":"","zh":"在家庭中，單親父母既失去另一半來共同教養子女，又要對孩子付出更多的愛，免得他們的情緒和行為因失去父親或母親的打擊而受到影響，因此在適應的初期階段是非常辛苦的。經過一段時間的調適以後，父母親就要以平常心面對子女，不能因可憐孩子而過度寵愛，或用物質彌補，這樣孩子才能正常成長。","pinyin":"","en":"Trong gia đình, cha mẹ đơn thân vừa mất người cùng dạy dỗ con, lại phải dành cho con nhiều tình yêu hơn, kẻo cảm xúc và hành vi của con bị ảnh hưởng bởi cú sốc mất cha hoặc mẹ, nên giai đoạn đầu thích nghi rất vất vả. Sau một thời gian điều chỉnh, cha mẹ phải đối xử với con bằng tâm thế bình thường, không thể vì thương con mà cưng chiều quá mức hay bù đắp bằng vật chất, như vậy con mới phát triển bình thường."},{"speaker":"","zh":"總之，單親父母應該先學習讓自己獨立，再處理前次婚姻留下的創痛，遇到適合對象，仍可再開創自己的第二春。","pinyin":"","en":"Tóm lại, cha mẹ đơn thân nên học cách tự lập trước, rồi xử lý vết thương lòng từ cuộc hôn nhân trước, gặp người phù hợp vẫn có thể mở ra mùa xuân thứ hai của mình."}],"questions":[{"prompt":"什麼是單親家庭？","options":["雙親之一單獨與子女生活的家庭","沒有孩子的家庭","祖父母撫養孩子的家庭","有很多孩子的家庭"],"correct":0},{"prompt":"現代人對單親家庭的看法怎麼樣？","options":["單親家庭不是破碎家庭，不一定過不幸的生活","單親家庭一定很不幸","單親家庭都很有錢","不能接受單親家庭"],"correct":0},{"prompt":"有些單親爸爸為什麼逃避婚姻？","options":["要付贍養費，經濟壓力大","他們不喜歡女人","孩子不同意","他們太忙了"],"correct":0},{"prompt":"父母調適以後應該怎麼對待子女？","options":["以平常心面對，不過度寵愛或用物質彌補","給他們很多錢","讓他們自己生活","不管他們"],"correct":0}]});
