  GRAMMAR.push({ structure: "……因……變得（SV）", usage: "\"…vì… mà trở nên (tính từ)\".", lesson: "P5-10", examples: [ex("清澈的海洋因垃圾的汙染變得死氣沉沉。", '', "Biển trong xanh vì rác ô nhiễm mà trở nên chết chóc."), ex("爸爸的身體因戒菸變得比以前健康多了。", '', "Sức khỏe bố vì cai thuốc mà tốt hơn trước nhiều.")] });
  GRAMMAR.push({ structure: "……因……變成（N）", usage: "\"…vì… mà biến thành (danh từ)\".", lesson: "P5-10", examples: [ex("茂密的森林因被濫伐變成乾枯的荒山。", '', "Rừng rậm vì bị chặt phá mà biến thành núi trọc khô cằn."), ex("他最近因心情不好每天喝很多的酒，變成了酒鬼。", '', "Gần đây anh vì buồn mà ngày nào cũng uống nhiều rượu, thành kẻ nghiện rượu.")] });
  GRAMMAR.push({ structure: "怎不令人（SV）？", usage: "\"Sao không khiến người ta… được?\": câu hỏi tu từ nhấn mạnh cảm xúc.", lesson: "P5-10", examples: [ex("人類把這個僅有的，獨一無二的美麗家園，破壞到這種慘不忍睹的程度，怎不令人惋惜！", '', "Loài người phá hoại ngôi nhà đẹp độc nhất vô nhị này đến mức thảm hại, sao không khiến người ta tiếc nuối!"), ex("她畢業了，又找到了好工作，怎不令人羨慕？", '', "Cô ấy tốt nghiệp lại tìm được việc tốt, sao không khiến người ta ghen tị?")] });
  GRAMMAR.push({ structure: "不論……也好，……也好，……都……", usage: "\"Dù… hay…, đều…\": mọi trường hợp đều như nhau.", lesson: "P5-10", examples: [ex("不論高峰會議討論也好，家庭學校推行也好，我們每個人都應該有一份神聖的使命。", '', "Dù là hội nghị thượng đỉnh bàn bạc hay gia đình, trường học thực hiện, mỗi chúng ta đều nên có một sứ mệnh thiêng liêng."), ex("不論成功也好，失敗也好，都要保持鬥志。", '', "Dù thành công hay thất bại đều phải giữ vững ý chí.")] });
  CONVERSATIONS.push({"title":"實用視聽華語5 · 第十課 人人都是環保尖兵","lines":[{"speaker":"","zh":"地球不再美麗了。你、我、他都有責任；人人都是罪魁禍首。可是我們大家都還不清醒，都還不認錯，仍然一天一天不斷地在刻意破壞我們唯一能生存的地方——地球。","pinyin":"","en":"Trái Đất không còn đẹp nữa. Bạn, tôi, anh ấy đều có trách nhiệm; ai cũng là thủ phạm. Nhưng chúng ta vẫn chưa tỉnh ngộ, chưa nhận lỗi, vẫn ngày qua ngày không ngừng cố ý phá hoại nơi duy nhất ta có thể sinh tồn — Trái Đất."},{"speaker":"","zh":"清澈的海洋因垃圾的汙染變得死氣沉沉；茂密的森林因被濫伐變成乾枯的荒山；清幽的原野因工廠的濃煙與廢氣變得烏煙瘴氣；山邊的溪流也因污水及化學廢水的流入成為混濁的臭溝。這樣下去，地球還能美麗嗎？人類把這個僅有的，獨一無二的美麗家園，破壞到這種慘不忍睹的程度，怎不令人惋惜！","pinyin":"","en":"Biển trong xanh vì rác ô nhiễm mà trở nên chết chóc; rừng rậm vì bị chặt phá mà thành núi trọc khô cằn; đồng nội yên tĩnh vì khói đặc và khí thải nhà máy mà mù mịt khói bụi; dòng suối bên núi cũng vì nước bẩn và nước thải hóa chất đổ vào mà thành rãnh nước thối đục ngầu. Cứ thế này, Trái Đất còn đẹp được sao? Loài người phá hoại ngôi nhà đẹp duy nhất, độc nhất vô nhị này đến mức thảm hại không nỡ nhìn, sao không khiến người ta tiếc nuối!"},{"speaker":"","zh":"日趨嚴重的情況不只是在地球表面上，甚至在地球上空保護我們的臭氧層都成了百孔千瘡的破網，太陽最有威力的紫外線，現在都能直接傷害到我們的皮膚了。更令人擔心的是，溫室效應引起全球暖化，可能帶來更多天災人禍。","pinyin":"","en":"Tình hình ngày càng nghiêm trọng không chỉ trên bề mặt Trái Đất, ngay cả tầng ôzôn bảo vệ chúng ta trên bầu trời cũng đã thành tấm lưới rách lỗ chỗ, tia cực tím mạnh nhất của mặt trời giờ có thể trực tiếp làm hại da ta. Đáng lo hơn, hiệu ứng nhà kính gây nóng lên toàn cầu, có thể mang đến nhiều thiên tai nhân họa hơn."},{"speaker":"","zh":"1970年4月22日在美國舉行的第一屆「地球日」活動，是全球環保運動的新起點。後來，數千名環保人士站出來，登高一呼，促使一百多個國家成立了專門負責環保工作的單位。透過這些單位，許多國家制定了各項避免污染的法規。1992年在巴西舉行的第一屆地球高峰會議，目的便是要解決地球溫度升高、森林濫伐等嚴重的問題。1997年十二月，各國代表又在日本舉行會議，通過「京都議定書」，規定減少二氧化碳等溫室氣體的排放量，防止氣候的改變對人類造成更大的傷害。","pinyin":"","en":"Ngày Trái Đất đầu tiên tổ chức ở Mỹ ngày 22/4/1970 là khởi điểm mới của phong trào môi trường toàn cầu. Sau đó, hàng nghìn nhà hoạt động môi trường đứng lên kêu gọi, thúc đẩy hơn một trăm nước lập cơ quan chuyên trách bảo vệ môi trường. Thông qua các cơ quan này, nhiều nước ban hành các quy định tránh ô nhiễm. Hội nghị thượng đỉnh Trái Đất đầu tiên ở Brazil năm 1992 nhằm giải quyết các vấn đề nghiêm trọng như nhiệt độ Trái Đất tăng, chặt phá rừng. Tháng 12/1997, đại biểu các nước lại họp ở Nhật, thông qua \"Nghị định thư Kyoto\", quy định giảm lượng phát thải khí nhà kính như CO2, ngăn biến đổi khí hậu gây hại lớn hơn cho loài người."},{"speaker":"","zh":"人人在注意這個大問題時，應該先捫心自問：我是不是每天製造髒亂的垃圾？然後由小處著手，從自己做起。其實家庭、學校就是最理想的，推行環保觀念的重鎮。父母師長若以身作則，孩子天天耳濡目染，自然而然會知道：如何將垃圾分類，做好資源回收；如何愛惜物資，節省電力；如何保護樹木與動物，免得破壞大自然的生態景觀。","pinyin":"","en":"Khi quan tâm đến vấn đề lớn này, mỗi người nên tự hỏi trước: tôi có phải ngày nào cũng tạo ra rác bẩn không? Rồi bắt đầu từ việc nhỏ, từ chính mình. Thật ra gia đình, trường học là nơi lý tưởng nhất để phổ biến ý thức bảo vệ môi trường. Cha mẹ thầy cô nếu lấy mình làm gương, trẻ ngày ngày nghe nhìn mà thấm, tự nhiên sẽ biết: phân loại rác, tái chế tài nguyên thế nào; quý trọng vật dụng, tiết kiệm điện ra sao; bảo vệ cây cối và động vật thế nào để khỏi phá hoại cảnh quan sinh thái tự nhiên."},{"speaker":"","zh":"總之，不論高峰會議討論也好，家庭學校推行也好，我們每個人都應該有一份神聖的使命——環保工作從自己做起。所以說，人人都是環保尖兵。","pinyin":"","en":"Tóm lại, dù là hội nghị thượng đỉnh bàn bạc hay gia đình, trường học thực hiện, mỗi chúng ta đều nên có một sứ mệnh thiêng liêng — bảo vệ môi trường bắt đầu từ chính mình. Vì vậy, ai cũng là chiến sĩ tiên phong bảo vệ môi trường."}],"questions":[{"prompt":"作者為什麼說人人都是罪魁禍首？","options":["大家都還不清醒、不認錯，不斷地破壞地球","只有工廠破壞地球","政府沒有制定法規","地球本來就不美麗"],"correct":0},{"prompt":"臭氧層破了會有什麼影響？","options":["太陽的紫外線能直接傷害我們的皮膚","天氣變冷","森林變多","海水變乾淨"],"correct":0},{"prompt":"全球環保運動的新起點是什麼？","options":["1970年在美國舉行的第一屆「地球日」","1992年的地球高峰會議","1997年的京都議定書","一百多個國家成立環保單位"],"correct":0},{"prompt":"「京都議定書」規定什麼？","options":["減少二氧化碳等溫室氣體的排放量","禁止砍樹","禁止吸菸","垃圾要分類"],"correct":0},{"prompt":"作者認為推行環保觀念最理想的地方是哪裡？","options":["家庭和學校","工廠","政府","高峰會議"],"correct":0}]});
  // ---- 實用視聽華語5 · 第十一課 強化體質
