  GRAMMAR.push({ structure: "最……的……可能算是……了", usage: "\"Cái… nhất có lẽ phải kể đến…\".", lesson: "P5-12", examples: [ex("在西餐方面，最盛行的可能算是「沙拉吧」了。", '', "Về món Tây, thịnh hành nhất có lẽ là \"quầy salad\"."), ex("她最喜歡的花可能算是玫瑰了。", '', "Hoa cô ấy thích nhất có lẽ là hoa hồng.")] });
  GRAMMAR.push({ structure: "……之餘", usage: "\"Sau khi…, ngoài lúc…\": khoảng thời gian / trạng thái còn lại sau việc chính.", lesson: "P5-12", examples: [ex("大快朵頤之餘，誰會想到一餐下來居然沒犧牲任何一條生命。", '', "Sau khi ăn uống thỏa thích, ai ngờ cả bữa chẳng hy sinh một sinh mạng nào."), ex("有些人常在工作之餘去當義工。", '', "Có người thường làm tình nguyện ngoài giờ làm việc.")] });
