  GRAMMAR.push({ structure: "……帶給……", usage: "\"…mang lại cho…\".", lesson: "P5-15", examples: [ex("這種隨遇而安、飄忽不定的生活方式，帶給他們新鮮感與無限的滿足。", '', "Lối sống tùy duyên, trôi nổi này mang lại cho họ cảm giác mới mẻ và sự thỏa mãn vô hạn."), ex("喜劇片總是帶給觀眾很多歡樂。", '', "Phim hài luôn mang lại cho khán giả nhiều niềm vui.")] });
