  GRAMMAR.push({ structure: "V遍", usage: "\"V khắp, V hết\": làm khắp một phạm vi.", lesson: "P5-16", examples: [ex("幾十年下來，不僅演遍大江南北……", '', "Mấy chục năm, không chỉ diễn khắp nam bắc…"), ex("他走遍全世界，去拍保護自然生態的影片。", '', "Anh đi khắp thế giới quay phim về bảo vệ sinh thái.")] });
  GRAMMAR.push({ structure: "除了……還得……", usage: "\"Ngoài… còn phải…\".", lesson: "P5-16", examples: [ex("喝茶時，除了燙壺、溫杯、注水等動作外，還得注意傳統的禮數。", '', "Khi uống trà, ngoài các động tác tráng ấm, làm ấm chén, rót nước, còn phải chú ý lễ nghi truyền thống."), ex("表演掌中戲，除了手中控制木偶，嘴裡還得發出聲音。", '', "Biểu diễn múa rối găng tay, ngoài điều khiển con rối trong tay, miệng còn phải phát ra tiếng.")] });
  GRAMMAR.push({ structure: "……沒有……，有的只是……", usage: "\"…không có…, chỉ có…\".", lesson: "P5-16", examples: [ex("李天祿喝茶時沒有「亦宛然」戲團雕樑畫棟的舞臺，有的只是一把不鏽鋼的水壺、宜興茶壺加上鶯歌燒製的茶杯而已。", '', "Khi uống trà, Lý Thiên Lộc không có sân khấu chạm trổ của đoàn \"Diệc Uyển Nhiên\", chỉ có một ấm đun inox, ấm trà Nghi Hưng cùng chén nung ở Oanh Ca mà thôi."), ex("這個山上沒有人，有的只是一群一群的羊。", '', "Trên núi này không có người, chỉ có từng đàn dê.")] });
  GRAMMAR.push({ structure: "……對……來說，不是……而是……", usage: "\"Đối với…, không phải… mà là…\".", lesson: "P5-16", examples: [ex("喝茶對他來說不是雅事，而是生活中必不可缺的事。", '', "Uống trà với ông không phải thú tao nhã mà là việc không thể thiếu trong cuộc sống."), ex("教書對他來說不是苦而是樂。", '', "Dạy học với anh không phải khổ mà là vui.")] });
  GRAMMAR.push({ structure: "大談……之道", usage: "\"Bàn nhiều về cách…, đạo…\".", lesson: "P5-16", examples: [ex("他得知唐朝陸羽寫《茶經》，大談喝茶之道後……", '', "Sau khi biết Lục Vũ đời Đường viết \"Trà Kinh\", bàn nhiều về đạo uống trà…"), ex("老人喜歡跟別人大談保養之道。", '', "Người già thích bàn với người khác về cách giữ gìn sức khỏe.")] });
  CONVERSATIONS.push({"title":"實用視聽華語5 · 第十六課 李天祿的掌中戲和茶藝","lines":[{"speaker":"","zh":"掌中戲大師李天祿，從十四歲起和掌中戲結緣，就一直執著於這份民俗技藝。幾十年下來，不僅演遍大江南北，贏得掌聲，同時也到歐美各國巡迴公演，教外國人看掌中戲，學掌中戲。另外，他還迷戀著一份茶香。他常說自己不喝茶，就吃不下飯。喝茶對他來說不是雅事，而是生活中必不可缺的事。他的學生也愛上了喝茶，他們除了學演掌中戲，就是學品茗。","pinyin":"","en":"Bậc thầy múa rối găng tay Lý Thiên Lộc từ năm 14 tuổi đã gắn bó với múa rối và kiên trì theo đuổi nghệ thuật dân gian này. Mấy chục năm, ông không chỉ diễn khắp nam bắc, được tán thưởng, mà còn lưu diễn khắp Âu Mỹ, dạy người nước ngoài xem và học múa rối. Ngoài ra, ông còn mê hương trà. Ông hay nói không uống trà thì ăn không trôi cơm. Uống trà với ông không phải thú tao nhã mà là việc không thể thiếu trong cuộc sống. Học trò ông cũng mê uống trà, ngoài học diễn múa rối thì là học thưởng trà."},{"speaker":"","zh":"茶藝在當時是很時髦的。喝茶時，除了燙壺、溫杯、注水等動作外，還得注意傳統的禮數。李天祿認為將茶水浸久一些較能泡出味道，所以晚些倒茶給客人成為一種尊重，先倒茶給自己則象徵謙遜。","pinyin":"","en":"Trà nghệ thời ấy rất thời thượng. Khi uống trà, ngoài các động tác tráng ấm, làm ấm chén, rót nước, còn phải chú ý lễ nghi truyền thống. Lý Thiên Lộc cho rằng ngâm trà lâu chút mới ra vị, nên rót trà cho khách muộn hơn là một sự tôn trọng, còn rót cho mình trước tượng trưng sự khiêm nhường."},{"speaker":"","zh":"李天祿喝茶時沒有「亦宛然」戲團雕樑畫棟的舞臺，有的只是一把不鏽鋼的水壺、宜興茶壺加上鶯歌燒製的茶杯而已。他認為好茶滑溜像茶油，入口即化，感覺上好像沒經過嘴巴就滑入喉嚨，但不久回味無窮，兩頰生津。李天祿的茶齡和戲齡一樣長，從二十二歲自組「亦宛然」戲團開始，平均一年三百臺戲，每場都必攜茶為伴。","pinyin":"","en":"Khi uống trà, Lý Thiên Lộc không có sân khấu chạm trổ lộng lẫy của đoàn \"Diệc Uyển Nhiên\", chỉ có một ấm đun inox, ấm trà Nghi Hưng cùng chén trà nung ở Oanh Ca mà thôi. Ông cho rằng trà ngon trơn mượt như dầu trà, vào miệng là tan, cảm giác như chưa qua miệng đã trôi xuống cổ, nhưng lát sau dư vị mãi không dứt, ngọt hậu đầy miệng. Tuổi uống trà của Lý Thiên Lộc dài bằng tuổi nghề diễn, từ năm 22 tuổi tự lập đoàn \"Diệc Uyển Nhiên\", trung bình mỗi năm 300 suất diễn, suất nào cũng mang trà theo."},{"speaker":"","zh":"雖然每天喝茶，李天祿卻很少自己買茶，平時不是茶農送茶，就是戲迷或是仰慕者送茶。茶的種類繁多，其中他最中意的是武夷茶。若有出國機會，他就找茶，買回好茶，與戲團中的人，以及好友、學生一同分享。","pinyin":"","en":"Tuy ngày nào cũng uống trà, Lý Thiên Lộc lại ít khi tự mua, thường không phải nông dân trồng trà tặng thì là khán giả hâm mộ hay người ngưỡng mộ tặng. Trà có rất nhiều loại, ông ưng nhất là trà Vũ Di. Có dịp ra nước ngoài là ông tìm trà, mua trà ngon về chia sẻ với người trong đoàn, bạn thân và học trò."},{"speaker":"","zh":"他得知唐朝陸羽寫《茶經》，大談喝茶之道後，曾經有興趣以陸羽為主角，編寫一齣掌中戲。他在嘗試中，發現木偶的握茶、品茶可以栩栩如生，令他十分興奮。可惜他還來不及實現這個願望，就以八十八歲的高齡離開人間了。","pinyin":"","en":"Sau khi biết Lục Vũ đời Đường viết \"Trà Kinh\" bàn nhiều về đạo uống trà, ông từng muốn lấy Lục Vũ làm nhân vật chính, soạn một vở múa rối. Khi thử nghiệm, ông phát hiện con rối cầm chén, thưởng trà có thể sống động như thật, khiến ông vô cùng phấn khởi. Tiếc là chưa kịp thực hiện mong ước này, ông đã qua đời ở tuổi 88."},{"speaker":"","zh":"李天祿控制著手中的木偶，傳神地演出悲歡離合，人情世事，自己也成了戲中人。他生前參加過好幾部電影的演出，其中有一部「戲夢人生」，演的是他年輕時代的故事。他一生獻身民俗技藝，又愛喝茶，「李天祿」這三個字將和「掌中戲」與「茶藝」結合在一起，永遠留在世人的記憶中。","pinyin":"","en":"Lý Thiên Lộc điều khiển con rối trong tay, diễn sống động những buồn vui tan hợp, nhân tình thế thái, bản thân ông cũng thành người trong vở diễn. Lúc sinh thời ông tham gia mấy bộ phim, trong đó có \"Hí mộng nhân sinh\" kể chuyện thời trẻ của ông. Cả đời cống hiến cho nghệ thuật dân gian, lại mê trà, ba chữ \"Lý Thiên Lộc\" sẽ gắn liền với \"múa rối găng tay\" và \"trà nghệ\", mãi lưu trong ký ức người đời."}],"questions":[{"prompt":"喝茶對李天祿來說是什麼？","options":["生活中必不可缺的事","一種雅事","偶爾的消遣","一種工作"],"correct":0},{"prompt":"為什麼晚些倒茶給客人？","options":["茶水浸久一些較能泡出味道，成為一種尊重","因為客人來晚了","因為茶太燙","因為主人想先喝"],"correct":0},{"prompt":"李天祿最中意哪一種茶？","options":["武夷茶","宜興茶","鶯歌茶","紅茶"],"correct":0},{"prompt":"李天祿想以誰為主角編寫掌中戲？","options":["唐朝寫《茶經》的陸羽","他自己","他的學生","一位茶農"],"correct":0}]});
  CONVERSATIONS.push({"title":"實用視聽華語5 · 第十六課 閱讀：扶老攜幼","lines":[{"speaker":"","zh":"孟嘗君是戰國時代齊國的貴族，做齊國的宰相很多年，他有個封國叫薛，薛國的人民每年要交稅給他，幾年來收成不好，人民欠了很多錢，孟嘗君要找人去收錢，他家有兩、三千個食客，只有一個叫馮諼的願意去。","pinyin":"","en":"Mạnh Thường Quân là quý tộc nước Tề thời Chiến Quốc, làm tể tướng nước Tề nhiều năm. Ông có đất phong tên Tiết, dân Tiết mỗi năm nộp thuế cho ông; mấy năm mất mùa, dân nợ rất nhiều tiền. Mạnh Thường Quân muốn tìm người đi thu tiền, nhà ông có hai ba nghìn thực khách, chỉ một người tên Phùng Huyên chịu đi."},{"speaker":"","zh":"臨走前馮諼問孟嘗君：「我收完了債，買些什麼東西回來呢？」孟嘗君說：「你看我家缺少什麼，就買什麼好了。」到了薛國，馮諼召集那些欠債的人都來對一下債券，對完以後，就假傳孟嘗君的命令說：「這些債都給你們了，不用還了。」於是把債券都燒了，人民高興極了，大聲喊著：萬歲！萬歲！","pinyin":"","en":"Trước khi đi Phùng Huyên hỏi: \"Thu nợ xong, tôi mua gì về?\" Mạnh Thường Quân đáp: \"Ngươi thấy nhà ta thiếu gì thì mua nấy.\" Đến đất Tiết, Phùng Huyên gọi những người nợ đến đối chiếu giấy nợ, xong thì giả truyền lệnh Mạnh Thường Quân: \"Những khoản nợ này cho các người cả, không phải trả.\" Rồi đốt hết giấy nợ, dân vui mừng hô vang: Vạn tuế! Vạn tuế!"},{"speaker":"","zh":"馮諼回到齊國，孟嘗君問：「買了什麼回來？」馮諼說：「我想您家中珍寶很多，馬房、狗房裡滿滿的都是名貴的狗馬，後宮都是美女，您家缺少的是『義』，所以我給您買了『義』。您只有一個小小的薛國，不但不能愛民如子，還要在他們身上取利，所以我假傳您的命令把債都給了人民，這就是我給您買的『義』啊！」孟嘗君聽了很不高興，但他沒說什麼。","pinyin":"","en":"Phùng Huyên về nước Tề, Mạnh Thường Quân hỏi: \"Mua gì về?\" Phùng Huyên nói: \"Tôi nghĩ nhà ngài châu báu rất nhiều, chuồng ngựa chuồng chó đầy chó ngựa quý, hậu cung toàn mỹ nữ, nhà ngài thiếu là 'nghĩa', nên tôi mua 'nghĩa' cho ngài. Ngài chỉ có đất Tiết nhỏ bé, không những không thương dân như con mà còn kiếm lợi từ họ, nên tôi giả lệnh ngài xóa nợ cho dân, đó chính là 'nghĩa' tôi mua cho ngài!\" Mạnh Thường Quân nghe rất không vui, nhưng không nói gì."},{"speaker":"","zh":"過了一年，孟嘗君失了官位，只好回到薛國去，這時眾多的食客都散去了，只有馮諼跟著他。走到離薛國還有百里遠的地方，只見人民扶老攜幼，全家出動，在路上歡迎孟嘗君，孟嘗君高興地回頭對馮諼說：「你一年前給我買的『義』，我今天才看到！」","pinyin":"","en":"Một năm sau, Mạnh Thường Quân mất chức, đành về đất Tiết, lúc này thực khách tản đi hết, chỉ Phùng Huyên đi theo. Còn cách đất Tiết trăm dặm đã thấy dân dìu già dắt trẻ, cả nhà ra đường đón ông. Mạnh Thường Quân vui mừng quay lại nói với Phùng Huyên: \"Cái 'nghĩa' ngươi mua cho ta một năm trước, hôm nay ta mới thấy!\""}],"questions":[{"prompt":"馮諼給孟嘗君買了什麼？","options":["『義』（把債券燒了，債都給了人民）","名貴的狗馬","珍寶","美女"],"correct":0},{"prompt":"為什麼人民扶老攜幼歡迎孟嘗君？","options":["因為一年前馮諼替孟嘗君把人民的債都免了","孟嘗君給他們錢","孟嘗君當了宰相","孟嘗君帶回很多珍寶"],"correct":0}]});
