  GRAMMAR.push({ structure: "……小小……竟……", usage: "\"…nhỏ bé như vậy mà lại…\": nhấn mạnh sự trái ngược giữa nhỏ bé và kết quả bất ngờ.", lesson: "P5-19", examples: [ex("地球在宇宙中只是一顆小小的星球，竟有無窮無盡的生物生存於其中。", '', "Trái Đất trong vũ trụ chỉ là một hành tinh nhỏ bé mà lại có vô số sinh vật sống trong đó."), ex("一隻小小的螞蟻竟能搬比牠身體重幾倍的東西。", '', "Một con kiến nhỏ xíu mà lại khiêng được vật nặng gấp mấy lần thân nó.")] });
  GRAMMAR.push({ structure: "……高居……之冠", usage: "\"…đứng đầu…\".", lesson: "P5-19", examples: [ex("例如非洲地區，人口的成長率高居世界之冠。", '', "Ví dụ khu vực châu Phi, tỷ lệ tăng dân số đứng đầu thế giới."), ex("臺北的人口總數高居臺灣之冠。", '', "Tổng dân số Đài Bắc đứng đầu Đài Loan.")] });
  GRAMMAR.push({ structure: "就……而言", usage: "\"Xét về…, về mặt…\".", lesson: "P5-19", examples: [ex("就經濟問題而言，人口成長率高的國家，必須提高經濟成長率。", '', "Về vấn đề kinh tế, nước có tỷ lệ tăng dân số cao phải nâng tỷ lệ tăng trưởng kinh tế."), ex("就本校而言，每年暑假是學生最多的時候。", '', "Với trường chúng tôi, kỳ nghỉ hè hằng năm là lúc đông học sinh nhất.")] });
  GRAMMAR.push({ structure: "……必須……，才能……", usage: "\"…phải…, mới có thể…\".", lesson: "P5-19", examples: [ex("人口成長率高的國家，必須提高經濟成長率，才能減輕人口膨脹的壓力。", '', "Nước có tỷ lệ tăng dân số cao phải nâng tăng trưởng kinh tế mới giảm được áp lực bùng nổ dân số."), ex("我們必須更加努力，才能克服工作上的困難。", '', "Chúng ta phải cố gắng hơn nữa mới vượt qua được khó khăn trong công việc.")] });
  CONVERSATIONS.push({"title":"實用視聽華語5 · 第十九課 人滿為患","lines":[{"speaker":"","zh":"地球在宇宙中只是一顆小小的星球，竟有無窮無盡的生物生存於其中。別的生物不談，現在我們來探討一下，究竟生活在地球上的人類有多少呢？","pinyin":"","en":"Trái Đất trong vũ trụ chỉ là một hành tinh nhỏ bé mà lại có vô số sinh vật sống trong đó. Chưa bàn đến sinh vật khác, giờ ta thử tìm hiểu xem rốt cuộc loài người sống trên Trái Đất có bao nhiêu?"},{"speaker":"","zh":"根據報導，1987年7月11日誕生於南斯拉夫的一個嬰兒，是世界上第五十億個人。資料也顯示，五十億人口剛好是1950年的兩倍；也就是說，在這三十七年中，世界人口有了這麼驚人的成長。那麼你能預估將來地球上有多少人口嗎？","pinyin":"","en":"Theo đưa tin, một em bé chào đời ở Nam Tư ngày 11/7/1987 là người thứ năm tỷ trên thế giới. Số liệu cũng cho thấy năm tỷ dân vừa đúng gấp đôi năm 1950; tức là trong ba mươi bảy năm này, dân số thế giới tăng trưởng đáng kinh ngạc như vậy. Vậy bạn có ước tính được tương lai Trái Đất có bao nhiêu người không?"},{"speaker":"","zh":"為什麼世界人口增加得如此快速呢？原因有二，一是出生率過高，二是死亡率降低。於是人口的成長率就以幾何級數不停地往上攀升。","pinyin":"","en":"Vì sao dân số thế giới tăng nhanh như vậy? Có hai nguyên nhân, một là tỷ lệ sinh quá cao, hai là tỷ lệ tử vong giảm. Thế là tỷ lệ tăng dân số không ngừng leo thang theo cấp số nhân."},{"speaker":"","zh":"在出生率過高的問題上，研究發現，這些快速增加的人口，有不少出生於開發中國家與未開發地區。例如非洲地區，人口的成長率高居世界之冠。人口的壓力，使得這些國家無法提高人民的生活品質與教育水準，因而引發了經濟問題、社會問題以及政治問題。","pinyin":"","en":"Về vấn đề tỷ lệ sinh quá cao, nghiên cứu phát hiện số dân tăng nhanh này phần nhiều sinh ở các nước đang phát triển và vùng chưa phát triển. Ví dụ châu Phi, tỷ lệ tăng dân số đứng đầu thế giới. Áp lực dân số khiến các nước này không thể nâng cao chất lượng sống và trình độ giáo dục của người dân, từ đó gây ra vấn đề kinh tế, xã hội và chính trị."},{"speaker":"","zh":"就經濟問題而言，人口成長率高的國家，必須提高經濟成長率，才能減輕人口膨脹的壓力。但是這個理想，並不容易實現。因為這些多半依賴農產品賺取外匯的國家，要是受到國際市場的限制，出口就會減少，如果再遭受天災人禍，往往出現嚴重的饑荒。這樣怎能提高他們的經濟成長呢？","pinyin":"","en":"Về kinh tế, nước có tỷ lệ tăng dân số cao phải nâng tỷ lệ tăng trưởng kinh tế mới giảm được áp lực bùng nổ dân số. Nhưng lý tưởng này không dễ thực hiện. Vì những nước phần lớn dựa vào nông sản để kiếm ngoại tệ này, nếu bị thị trường quốc tế hạn chế thì xuất khẩu giảm, nếu lại gặp thiên tai nhân họa thì thường xảy ra nạn đói nghiêm trọng. Như vậy sao nâng được tăng trưởng kinh tế?"},{"speaker":"","zh":"在控制出生率上，這些國家雖然也採用過種種方法，比如倡導節育，或者像一胎化這樣限制生育的人口政策，但因「人口多，人力就足」的觀念難以改變，都無法有效實行，阻擋不住人口膨脹的洪流。","pinyin":"","en":"Về kiểm soát tỷ lệ sinh, các nước này tuy đã áp dụng nhiều cách như đề xướng kế hoạch hóa, hay chính sách hạn chế sinh như một con, nhưng vì quan niệm \"đông người thì đủ sức lao động\" khó thay đổi, đều không thực hiện hiệu quả, không ngăn được dòng lũ bùng nổ dân số."},{"speaker":"","zh":"談到死亡率降低，原因也不少，例如歐美及東北亞各國，因醫藥發達、生活品質提高、注意環境衛生等因素，逐漸成為死亡率降低的地區。這些因素，使人類的壽命延長，老年人口的比率日漸增多，導致人口結構失衡。在這種情形下，越來越多的老年人成為依賴人口，而兒童的求學時期又較長，因此造成必須奉養老人及撫育兒童的勞動人口負擔過重，形成一些社會問題。","pinyin":"","en":"Nói đến tỷ lệ tử vong giảm, nguyên nhân cũng nhiều, ví dụ các nước Âu Mỹ và Đông Bắc Á, nhờ y dược phát triển, chất lượng sống nâng cao, chú ý vệ sinh môi trường…, dần trở thành khu vực tỷ lệ tử vong giảm. Những yếu tố này khiến tuổi thọ con người kéo dài, tỷ lệ người già ngày càng tăng, dẫn đến cơ cấu dân số mất cân bằng. Trong tình hình đó, ngày càng nhiều người già trở thành người phụ thuộc, mà thời gian đi học của trẻ lại dài, khiến lực lượng lao động phải phụng dưỡng người già và nuôi dạy trẻ gánh nặng quá mức, hình thành một số vấn đề xã hội."},{"speaker":"","zh":"近年來，除了人口問題之外，我們也看到日趨嚴重的生態問題，大自然已被破壞殆盡。這人滿為患而又不再美麗的地球，還能算是宇宙中一顆閃亮的星球嗎？","pinyin":"","en":"Những năm gần đây, ngoài vấn đề dân số, ta còn thấy vấn đề sinh thái ngày càng nghiêm trọng, thiên nhiên đã bị phá hoại gần hết. Trái Đất quá tải người mà lại không còn đẹp này, còn có thể coi là một ngôi sao lấp lánh trong vũ trụ không?"}],"questions":[{"prompt":"世界人口增加得這麼快速的原因是什麼？","options":["出生率過高、死亡率降低","戰爭太多","移民太多","食物太多"],"correct":0},{"prompt":"人口成長率高居世界之冠的是哪裡？","options":["非洲地區","歐美","東北亞","南斯拉夫"],"correct":0},{"prompt":"為什麼限制生育的人口政策無法有效實行？","options":["「人口多，人力就足」的觀念難以改變","政府不重視","人民太窮","醫藥不發達"],"correct":0},{"prompt":"死亡率降低帶來什麼問題？","options":["老年人口增多，人口結構失衡，勞動人口負擔過重","饑荒","出生率提高","經濟成長太快"],"correct":0}]});
